/* torproc.c - generate torrc, spawn tor, wait for bootstrap */
#include "torproc.h"
#include "control.h"
#include "state.h"
#include "sock.h"

#ifdef _WIN32
#include <direct.h>
static PROCESS_INFORMATION g_pi;
#endif

static void write_torrc(const char *path)
{
    FILE *f = fopen(path, "w");
    if (!f) {
        fprintf(stderr, "FATAL: cannot write %s\n", path);
        exit(1);
    }
    fprintf(f,
        "# generated by tor_rotate " ROT_VERSION "\n"
        "SocksPort 127.0.0.1:%d\n"
        "ControlPort 127.0.0.1:%d\n"
        "CookieAuthentication 1\n"
        "DataDirectory %s\n"
        "Log notice file %s/tor.log\n"
        "SafeLogging 1\n",
        g_cfg.socks_port, g_cfg.control_port, g_cfg.data_dir, g_cfg.data_dir);

    if (g_cfg.upstream_proxy[0])
        fprintf(f, "Socks5Proxy %s\n", g_cfg.upstream_proxy);
    if (g_cfg.exit_include[0])
        fprintf(f, "ExitNodes %s\nStrictNodes 1\n", g_cfg.exit_include);
    if (g_cfg.exit_exclude[0])
        fprintf(f, "ExcludeNodes %s\nStrictNodes 1\n", g_cfg.exit_exclude);

    /* bridges: lyrebird (obfs4/meek_lite) shipped with the tor expert bundle */
    if (g_cfg.n_bridges > 0) {
        char pt[768];
        snprintf(pt, sizeof pt, "%s/pluggable_transports/lyrebird.exe", g_cfg.ptdir);
        fprintf(f,
            "UseBridges 1\n"
            "ClientTransportPlugin obfs4 exec %s\n"
            "ClientTransportPlugin meek_lite exec %s\n",
            pt, pt);
        for (int i = 0; i < g_cfg.n_bridges; i++)
            fprintf(f, "Bridge %s\n", g_cfg.bridge_lines[i]);
    }

    if (g_cfg.geoip_path[0]) {
        fprintf(f, "GeoIPFile %s\n", g_cfg.geoip_path);
        /* sibling geoip6 (same dir), if present tor just warns when missing */
        char g6[768];
        str_copy(g6, sizeof g6, g_cfg.geoip_path);
        char *cut = strrchr(g6, '/');
        char *bcut = strrchr(g6, '\\');
        char *p = cut > bcut ? cut : bcut;
        if (p) {
            snprintf(p + 1, sizeof g6 - (p + 1 - g6), "geoip6");
            fprintf(f, "GeoIPv6File %s\n", g6);
        }
    }

    /* client-only is tor's default when no ORPort is set */
    fclose(f);
}

static int wait_bootstrap(void)
{
    char buf[1024];
    int last_milestone = -1;
    int authed = 0;

    for (int attempt = 0; attempt < 600; attempt++) {   /* up to ~10min */
        if (g_app.ctrl.s == SOCK_INVALID) {
            if (ctrl_connect(&g_app.ctrl, g_cfg.control_port) != 0) {
                msleep(1000);
                continue;
            }
            authed = 0;
        }
        if (!authed) {
            if (ctrl_auth(&g_app.ctrl, g_cfg.data_dir) != 0) {
                sock_close(g_app.ctrl.s);
                g_app.ctrl.s = SOCK_INVALID;
                msleep(1000);
                continue;
            }
            authed = 1;
        }
        if (ctrl_get_bootstrap(&g_app.ctrl, buf, sizeof buf) != 0) {
            /* connection broke during wait: drop it and reconnect */
            sock_close(g_app.ctrl.s);
            g_app.ctrl.s = SOCK_INVALID;
            authed = 0;
            msleep(1000);
            continue;
        }
        if (str_icontains(buf, "progress=100")) {
            g_app.tor_ready = 1;
            return 0;
        }
        char *p = strstr(buf, "PROGRESS=");
        if (p) {
            int pct = atoi(p + 9);
            if (pct / 20 > last_milestone) {
                last_milestone = pct / 20;
                log_line("bootstrap %d%%", pct);
            }
        }
        msleep(1000);
    }
    fprintf(stderr, "FATAL: tor did not bootstrap in time (see %s/tor.log)\n", g_cfg.data_dir);
    return -1;
}

int torproc_launch(void)
{
    ensure_dir(g_cfg.data_dir);
    char torrc[768];
    snprintf(torrc, sizeof torrc, "%s/torrc", g_cfg.data_dir);
    write_torrc(torrc);

    char cmdline[1600];
    snprintf(cmdline, sizeof cmdline, "\"%s\" -f \"%s\"", g_cfg.tor_path, torrc);

#ifdef _WIN32
    STARTUPINFOA si;
    memset(&si, 0, sizeof si);
    si.cb = sizeof si;
    si.dwFlags = STARTF_USESHOWWINDOW;
    si.wShowWindow = SW_HIDE;
    if (!CreateProcessA(NULL, cmdline, NULL, NULL, FALSE,
                        CREATE_NO_WINDOW, NULL, NULL, &si, &g_pi)) {
        log_line("FATAL: cannot spawn tor (%lu)", GetLastError());
        return -1;
    }
#else
    pid_t pid = fork();
    if (pid == 0) {
        execl(g_cfg.tor_path, g_cfg.tor_path, "-f", torrc, (char *)NULL);
        _exit(127);
    }
    if (pid < 0) return -1;
#endif
    log_line("tor spawned: %s", g_cfg.tor_path);
    log_line("waiting for tor bootstrap (check %s/tor.log on failure)...", g_cfg.data_dir);
    if (wait_bootstrap() != 0) {
        fprintf(stderr, "FATAL: tor did not bootstrap in time (see %s/tor.log)\n", g_cfg.data_dir);
        return -1;
    }
    log_line("tor bootstrapped. control port authenticated.");
    return 0;
}

void torproc_stop(void)
{
#ifdef _WIN32
    if (g_pi.hProcess) {
        TerminateProcess(g_pi.hProcess, 0);
        CloseHandle(g_pi.hThread);
        CloseHandle(g_pi.hProcess);
        g_pi.hProcess = NULL;
    }
#endif
}
